<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Biography; use App\Models\ContentItem; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class BiographyController extends Controller {
 public function edit() { $this->authorize('permission','content.update'); $biography=Biography::with('contentItem','sections')->first(); return view('admin.biography.edit',compact('biography')); }
 public function update(Request $request) { $this->authorize('permission','content.update'); $data=$request->validate(['name'=>['required','string','max:255'],'excerpt'=>['nullable','string'],'body'=>['nullable','string'],'is_visible'=>['required','boolean'],'social_links'=>['nullable','array'],'sections'=>['nullable','array'],'sections.*.id'=>['nullable','integer'],'sections.*.type'=>['required','in:qualification,work,participation,achievement'],'sections.*.title'=>['required','string','max:255'],'sections.*.body'=>['nullable','string'],'sections.*.sort_order'=>['required','integer','min:0'],'sections.*.is_visible'=>['required','boolean']]); DB::transaction(function()use($data){$content=ContentItem::firstOrCreate(['type'=>'biography'],['title'=>$data['name'],'slug'=>'biography','status'=>'draft']);$content->update(['title'=>$data['name'],'excerpt'=>$data['excerpt'],'body'=>$data['body'],'status'=>$data['is_visible']?'published':'draft','published_at'=>$data['is_visible']?($content->published_at??now()):null,'meta'=>['social_links'=>$data['social_links']??[]]]);$bio=Biography::firstOrCreate(['content_item_id'=>$content->id]);$ids=[];foreach($data['sections']??[] as $section){$item=$bio->sections()->updateOrCreate(['id'=>$section['id']??null],$section);$ids[]=$item->id;}$bio->sections()->whereNotIn('id',$ids)->delete();}); return back()->with('status','تم حفظ السيرة الذاتية.'); }
}
